cache_key="$(printf '%s' "$LINEAR_API_KEY" | cksum | awk '{print $1}')"
TEAMS_CACHE="${LINEAR_TEAMS_CACHE:-/tmp/linear-teams-${cache_key}.json}"

refresh_teams_cache() {
  gql "{ teams { nodes { id key name } } }" > "$TEAMS_CACHE"
}

load_teams() {
  if [[ ! -f "$TEAMS_CACHE" ]]; then
    refresh_teams_cache
  fi
  cat "$TEAMS_CACHE"

results = {}
for cal_id in get_calendar_ids():
    params = {
        'maxResults': parsed.max_results,
        'singleEvents': 'true',
        'orderBy': 'startTime',
    }
    if parsed.time_min:
        params['timeMin'] = parsed.time_min
    if parsed.time_max:
        params['timeMax'] = parsed.time_max
    url = f"{BASE_URL}/calendars/{urllib.parse.quote(cal_id)}/events?{urllib.parse.urlencode(params)}"
    resp = request('GET', url)
    results[cal_id] = resp.get('items', [])
# Output a combined JSON mapping calendar ID -> list of events
print(json.dumps(results, indent=2))

function decompressBody(buffer, contentEncoding) {
  if (!contentEncoding) return buffer;
  const encoding = String(contentEncoding).toLowerCase();
  try {
    if (encoding.includes('gzip')) return zlib.gunzipSync(buffer);
    if (encoding.includes('deflate')) return zlib.inflateSync(buffer);
    if (encoding.includes('br')) return zlib.brotliDecompressSync(buffer);
  } catch {
    // 解压失败时直接返回原始数据，避免影响主流程
  }
  return buffer;
